def build_dataset(raw_list, level):
    words = []
    for idx, item in enumerate(raw_list):
        hanzi, pinyin, translations, pos, s_hanzi, s_pinyin, s_trans = item
        words.append({
            "id": f"hsk{level}-{idx+1:03d}",
            "level": level,
            "hanzi": hanzi,
            "pinyin": pinyin,
            "translations": translations,
            "partOfSpeech": pos,
            "exampleSentence": {
                "hanzi": s_hanzi,
                "pinyin": s_pinyin,
                "translation": s_trans
            }
        })
    return words

levels = [
    (1, hsk1_raw),
    (2, hsk2_raw),
    (3, hsk3_raw),
    (4, hsk4_raw),
    (5, hsk5_raw),
]

os.makedirs("public/data", exist_ok=True)

for lvl, raw in levels:
    data = build_dataset(raw, lvl)
    filepath = f"public/data/hsk{lvl}.json"
    with open(filepath, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    print(f"Generated {filepath} with {len(data)} words.")

print("All HSK datasets successfully generated.")
